'use strict';
const PLANNER_KEY='fw-planner-v1';
let plannerStore={plans:{},funds:{}},plannerTab=host.workflow?'setup':'canvas',scenarioChoice='balanced',scenarioDraft=null;
try{const saved=JSON.parse(localStorage.getItem(PLANNER_KEY)||'null');if(saved&&saved.plans&&saved.funds&&typeof saved.plans==='object'&&!Array.isArray(saved.plans)&&typeof saved.funds==='object'&&!Array.isArray(saved.funds))plannerStore=saved}catch{}
const planLanes={must:{name:'Must pay',description:'The commitments that come first',icon:'▣',color:'#8d9a7c',background:'#edf1e6'},everyday:{name:'Everyday life',description:'Room for the way you actually live',icon:'◒',color:'#b0a079',background:'#f6f1e4'},future:{name:'Future you',description:'Investments and tomorrow’s goals',icon:'♧',color:'#7e9e8f',background:'#eaf2eb'},extras:{name:'This month’s extras',description:'Make space for something different',icon:'✧',color:'#b39a87',background:'#f6ece4'},buffer:{name:'Breathing room',description:'A little margin goes a long way',icon:'〰',color:'#9aa57d',background:'#f1f4e7'}};
const planKindNames={income:'Expected income',funding:'Household funding',expense:'Consumption',investment:'Investment contribution',withdrawal:'Investment withdrawal',card:'Card payment',transfer:'Internal transfer',reserve:'Cash earmark',reimbursement:'Expected reimbursement'};
const plannerMonth=m=>new Date(m+'-02T12:00:00').toLocaleDateString('en-IN',{month:'long'});
function shiftMonth(m,n){let d=new Date(m+'-02T12:00:00');d.setMonth(d.getMonth()+n);return d.toISOString().slice(0,7)}
function planKey(){return [state.scope,state.currency,state.month].join(':')}
function planSave(){localStorage.setItem(PLANNER_KEY,JSON.stringify(plannerStore));sessionStorage.setItem('fw-planner-month',state.month)}
function planBanks(){return accounts().filter(x=>x.type==='bank')}
function plannerSeed(){
 const previous=shiftMonth(state.month,-1),items=[];
 const add=(t,kind,lane)=>items.push({id:'pi-'+(items.length+1),title:t.description,amount:t.amount,kind,lane,day:Math.min(+t.date.slice(8),new Date(+state.month.slice(0,4),+state.month.slice(5),0).getDate()),category:t.category,source:monthName(previous)+' observed · editable estimate',enabled:true,account:t.account,person:t.person,timing:'once',matchIds:[]});
 for(const t of (host.workflow?[]:data(previous)))if(t.type==='income')add(t,'income','income');else if(t.type==='investment')add(t,'investment','future');else if(t.type==='expense'&&(t.subscription||t.recurring))add(t,'expense','must');
 for(const c of (host.workflow?[]:byCategory(data(previous)))){const remaining=c.amount-sum(items.filter(x=>x.kind==='expense'&&x.category===c.name),x=>x.amount);if(remaining>0)items.push({id:'pi-'+(items.length+1),title:c.name,amount:Math.round(remaining*100)/100,kind:'expense',lane:'everyday',day:7,category:c.name,source:monthName(previous)+' net spending · editable allowance',enabled:true,account:planBanks()[0]?.name||'Manual opening pool',person:host.person,timing:'weekly',matchIds:[]});}
 const banks=planBanks(),known=sum(banks.filter(x=>x.balance!==null),x=>x.balance-(x.reserve||0));
 return {name:plannerMonth(state.month)+' plan',status:'draft',revision:1,opening:known,openingSource:'Latest recorded bank/cash balances less existing earmarks · verify for the planned month',partial:true,cashFloor:0,items,scenarios:[],history:[],ritual:{},activeLinks:null};
}
function currentPlan(){let k=planKey();if(!plannerStore.plans[k]){plannerStore.plans[k]=plannerSeed();planSave()}return plannerStore.plans[k]}
function planRevise(reason){let p=currentPlan();p.history.push({revision:p.revision,date:new Date().toLocaleString('en-IN'),reason});p.revision++;if(p.status==='active'){p.status='draft';p.activeLinks=null}scenarioDraft=null;planSave()}
function planTotals(plan=currentPlan(),items=plan.items){let a=items.filter(x=>x.enabled),of=k=>sum(a.filter(x=>x.kind===k),x=>x.amount),income=of('income'),funding=of('funding'),reimbursements=of('reimbursement'),contributions=of('investment'),withdrawals=of('withdrawal'),spend=of('expense'),card=of('card'),reserve=of('reserve'),out=spend+contributions+card+reserve;return{income,funding,reimbursements,spend,invested:contributions-withdrawals,contributions,withdrawals,card,reserve,out,receipts:income+funding+reimbursements+withdrawals,unallocated:plan.opening+income+funding+reimbursements+withdrawals-out,available:plan.opening,total:plan.opening+income+funding+reimbursements+withdrawals}}
function planEvents(p=currentPlan(),items=p.items){let days=new Date(+state.month.slice(0,4),+state.month.slice(5),0).getDate(),events=[];for(let x of items.filter(x=>x.enabled&&x.kind!=='transfer')){let sign=['income','funding','withdrawal','reimbursement'].includes(x.kind)?1:-1,kind=x.kind==='reserve'?'earmark':sign>0?'receipt':'payment',dates=x.timing==='weekly'?[7,14,21,days]:[Math.max(1,Math.min(days,+x.day||1))];let amount=0;dates.forEach((day,i)=>{let amt=i===dates.length-1?x.amount-amount:Math.floor(x.amount/dates.length*100)/100;amount+=amt;events.push({day,amount:amt*sign,title:x.title,kind,itemId:x.id,account:x.account,destination:x.destination,source:x.source})})}return events.sort((a,b)=>a.day-b.day||(b.amount-a.amount))}
function planForecast(p=currentPlan(),items=p.items){let events=planEvents(p,items),n=new Date(+state.month.slice(0,4),+state.month.slice(5),0).getDate(),balance=p.opening,rows=[];for(let d=1;d<=n;d++){let dayEvents=events.filter(e=>e.day===d);balance+=sum(dayEvents,x=>x.amount);rows.push({day:d,balance,events:dayEvents})}let low=rows.reduce((a,b)=>b.balance<a.balance?b:a,{day:0,balance:p.opening});return{rows,events,low,end:rows.at(-1)?.balance??p.opening,below:rows.filter(x=>x.balance<p.cashFloor).length}}
function planFunding(p=currentPlan()){let available=p.opening,map={};for(let x of p.items.filter(x=>x.enabled&&!['income','funding','withdrawal','reimbursement','transfer'].includes(x.kind)).sort((a,b)=>a.day-b.day)){map[x.id]=available>=x.amount?'Funded now':available>0?'Partly funded now':'Needs future receipts';available-=x.amount}return map}
function planStatus(p=currentPlan()){return `<div class="plan-status"><span class="tag ${p.status==='draft'?'amber':p.status==='closed'?'gray':''}">${p.status==='draft'?'◌ Draft':p.status==='active'?'● Active':'✓ Closed'}</span><span class="revision">Revision ${p.revision}</span></div>`}
function plannerActiveBudget(){let p=plannerStore.plans[planKey()];return p?.activeLinks&&p.status!=='draft'?p.activeLinks:null}
function plannerHeader(){let p=currentPlan();return `<div class="plan-hero"><div><div class="eyebrow">A LITTLE INTENTION GOES A LONG WAY</div><h2>Make room for a good ${plannerMonth(state.month)}.</h2><p>Cover the essentials. Grow your future. Leave room for life.<br>Give the coming month a plan that feels like you.</p></div><div class="hero-tools"><button class="button primary" ${host.workflow?'data-plan-tab="setup"':'data-plan-action="ritual"'}>✧ Build my month</button><button class="button" data-plan-action="event">＋ What’s different this month?</button></div></div><div class="plan-tabs" role="tablist" aria-label="Planner views">${[...(host.workflow?[['setup','✓','Build budget']]:[]),['canvas','▦','Month canvas'],['calendar','▣','Cash calendar'],['scenarios','✧','What-if studio'],['funds','◉','Sinking funds'],['actual','⇄','Plan vs actual']].map(([k,i,n])=>`<button role="tab" aria-selected="${plannerTab===k}" class="${plannerTab===k?'active':''}" data-plan-tab="${k}"><span>${i}</span>${n}</button>`).join('')}</div>`}
function plannerMetrics(p=currentPlan()){let m=planTotals(p),f=planForecast(p);return `<div class="plan-metrics"><button class="plan-metric" data-plan-action="opening"><small>Available to plan now</small><strong class="num">${money(p.opening)}</strong><em>${p.partial?'◉ Partial balance coverage':'✓ Manually confirmed opening'} · edit starting funds</em></button><button class="plan-metric" data-plan-action="receipts"><small>Expected receipts</small><strong class="num">${money(m.receipts)}</strong><em>${money(m.income)} income${m.funding?' · '+money(m.funding)+' funding':''} · Future, not available yet</em></button><button class="plan-metric ${m.unallocated<0?'warn':'highlight'}" data-plan-action="allocation"><small>${m.unallocated<0?'Overallocated':'Still yours to give a purpose'}</small><strong class="num">${money(Math.abs(m.unallocated))}</strong><em>${m.unallocated<0?'Reduce commitments or revisit assumptions':'After spending, investments, card payments & earmarks'}</em></button><button class="plan-metric ${f.low.balance<p.cashFloor?'warn':''}" data-plan-tab="calendar"><small>Lowest projected available cash</small><strong class="num">${money(f.low.balance)}</strong><em>${f.low.day?f.low.day+' '+plannerMonth(state.month):'Opening position'} · ${p.partial?'Partial forecast':'Based on confirmed opening'}${f.below?' · '+f.below+' days below floor':''}</em></button></div>`}
function renderPlanner(){let p=currentPlan();$('#page-subtitle').textContent='A thoughtful plan for the month ahead.';$('#page-title').innerHTML='Planner<span class="heading-dot">.</span>';$('#greeting').textContent='LOOK AHEAD. FEEL MORE READY.';$('#coverage').innerHTML=`<p class="coverage-note"><i>◉</i> ${scopeName()} planning · ${state.scope==='household'?'Shared Family funds only · private balances excluded':'Expected income is separate from available cash'}<span style="margin-left:auto">${state.currency} · Browser-local plan</span></p>`;$$('.mobile-bottom [data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page==='Planner'));if(plannerTab!=='setup'&&!planBanks().length&&!p.items.length&&!p.openingConfirmed){$('#content').innerHTML=plannerHeader()+`<section class="panel plan-empty-currency"><h3>A clean slate in ${state.currency}</h3><p>No bank balances or prior activity are recorded in this currency.<br>Create a manual plan; balances remain unknown until you confirm an opening amount.</p><button class="button primary" data-plan-action="opening" style="margin-top:20px">Set starting funds</button><button class="button" data-plan-action="add-income" style="margin-top:20px">Add expected receipt</button></section>`;return}$('#content').innerHTML=plannerHeader()+(plannerTab==='setup'?plannerWorkflow():plannerTab==='funds'?plannerFundsView():plannerMetrics(p)+(plannerTab==='canvas'?plannerCanvas():plannerTab==='calendar'?plannerCalendar():plannerTab==='scenarios'?plannerScenarios():plannerActual()));if(plannerTab==='scenarios')updateScenarioNumbers()}
function plannerLane(key){let p=currentPlan(),meta=planLanes[key],items=p.items.filter(x=>x.lane===key),funding=planFunding(p);return `<section class="plan-lane" style="--lane-color:${meta.color};--lane-bg:${meta.background}"><div class="lane-head"><span class="lane-icon">${meta.icon}</span><div><h3>${meta.name}</h3><p>${meta.description}</p></div><div class="lane-total num">${money(sum(items.filter(x=>x.enabled),x=>x.amount))}<small>${items.filter(x=>x.enabled).length} planned ${items.filter(x=>x.enabled).length===1?'item':'items'}</small></div></div><div class="lane-items">${items.map(x=>`<div class="plan-item ${x.enabled?'':'disabled'}"><input class="item-toggle" type="checkbox" data-plan-toggle="${x.id}" aria-label="Include ${esc(x.title)}" ${x.enabled?'checked':''} ${p.status==='closed'?'disabled':''}><button class="item-details" data-plan-edit="${x.id}"><b>${esc(x.title)}</b><small>${x.timing==='weekly'?'Across 4 weekly portions':x.day+' '+plannerMonth(state.month)} · ${esc(x.person)} · ${esc(x.account)}${x.kind==='card'?' → '+esc(x.destination||'Card'):''}</small><span class="source-label">${esc(x.source)}</span></button><div class="item-amount num">${money(x.amount)}<small>${x.enabled?funding[x.id]||planKindNames[x.kind]:'Not included'}</small></div><button class="item-edit" data-plan-edit="${x.id}" aria-label="Edit ${esc(x.title)}">↗</button></div>`).join('')||'<p class="plan-help" style="padding:0 0 15px">Nothing planned here yet. Make room for something meaningful.</p>'}</div><button class="lane-add" data-plan-add="${key}" ${p.status==='closed'?'disabled':''}>＋ Add ${key==='extras'?'a one-off moment':key==='future'?'an investment or earmark':key==='buffer'?'a cash buffer':'a planned item'}</button></section>`}
function plannerCanvas(){let p=currentPlan(),m=planTotals(p),f=planForecast(p),receipts=p.items.filter(x=>['income','funding','withdrawal','reimbursement'].includes(x.kind)),alloc=[['Spending',m.spend,'#8da079'],['Net investment',m.invested,'#abc2af'],['Card payments',m.card,'#d5ba83'],['New cash earmarks',m.reserve,'#b8c49a'],['Unallocated',Math.max(0,m.unallocated),'#e1e7d7']];return `<div class="plan-grid"><div class="plan-main"><div class="plan-section-head"><div><h3>Your month, thoughtfully arranged</h3><p>Toggle an item to see what changes. Open it to make it yours.</p></div>${planStatus(p)}</div>${Object.keys(planLanes).map(plannerLane).join('')}<div class="plan-footer"><p>Plan items are intentions, not posted transactions.<br>All changes stay in this browser.</p><div class="plan-top-actions"><button class="button" data-plan-action="history">Revision history</button>${p.status==='draft'?'<button class="button primary" data-plan-action="activate">Review & activate →</button>':p.status==='active'?'<button class="button primary" data-plan-action="linked-budget">Open linked budget ↗</button><button class="button" data-plan-action="close-plan">Close month ✓</button>':'<button class="button" data-plan-action="reopen">Reopen as draft</button>'}</div></div></div><aside class="plan-aside"><section class="panel">${sectionHead('The bigger picture','One plan. Every kind of movement.')}<div class="allocation-meter">${alloc.map(([n,v,c])=>`<span title="${n}: ${money(v)}" style="background:${c};width:${Math.max(0,v)/Math.max(1,m.total)*100}%"></span>`).join('')}</div><div class="allocation-legend">${alloc.map(([n,v,c])=>`<div class="allocation-line"><span><i class="legend-dot" style="background:${c}"></i>${n}</span><b>${money(v)}</b></div>`).join('')}</div><button class="view-all" data-plan-action="allocation">Explain this plan ↗</button></section><section class="panel">${sectionHead('Your next receipts','Expected money ≠ money in hand')} ${receipts.map(x=>`<button class="commitment" data-plan-edit="${x.id}"><span class="date-box"><small>${plannerMonth(state.month).slice(0,3).toUpperCase()}</small><b>${x.day}</b></span><span class="detail"><b>${esc(x.title.split(' · ')[0])}</b><small>${x.kind==='income'?'Expected income':planKindNames[x.kind]} · ${esc(x.person)}</small></span><span class="money">${money(x.amount)}</span></button>`).join('')||'<p class="plan-help">No expected receipts yet.</p>'}<button class="view-all" data-plan-action="add-income">＋ Add expected receipt</button></section><div class="plan-callout"><h3>${f.below?'◷ Mind the timing':'✧ A little room to breathe'}</h3><p>${f.below?`Projected available cash dips below your ${money(p.cashFloor)} floor on ${f.below} days. Review timing before relying on future receipts.`:`Your lowest projected available cash is ${money(f.low.balance)}. ${p.partial?'One or more balances are unknown, so this is a partial forecast.':'Keep assumptions current as the month unfolds.'}`}</p><button class="button" data-plan-tab="calendar">See my cash calendar ↗</button></div><section class="panel"><div class="eyebrow">A GOOD QUESTION TO ASK</div><h2>Can that purchase fit?</h2><p class="intro" style="line-height:1.9;margin-top:8px">Try a purchase, protect your investments, and see what happens to your breathing room.</p><button class="view-all" data-plan-tab="scenarios">Open what-if studio ✧</button></section></aside></div>`}
function plannerCashSVG(f,p){let min=Math.min(0,p.cashFloor,...f.rows.map(r=>r.balance)),max=Math.max(p.cashFloor,p.opening,...f.rows.map(r=>r.balance),1)*1.08,y=v=>100-(v-min)/Math.max(1,max-min)*90,x=d=>15+(d-1)/Math.max(1,f.rows.length-1)*680,path=f.rows.map((r,i)=>(i?'L':'M')+x(r.day)+','+y(r.balance)).join(' ');return `<svg class="cash-line" viewBox="0 0 710 125" role="img" aria-label="Daily projected available cash. The dashed line is your chosen cash floor."><line x1="15" x2="695" y1="${y(p.cashFloor)}" y2="${y(p.cashFloor)}" stroke="#c4ac7c" stroke-dasharray="4 4"/><path d="${path} L695,105 L15,105 Z" fill="#eaf1e3"/><path d="${path}" fill="none" stroke="#7d9c68" stroke-width="2"/>${[1,7,14,21,f.rows.length].map(d=>`<text x="${x(d)}" y="122" text-anchor="middle" fill="#9aab89" font-size="9">${d} ${plannerMonth(state.month).slice(0,3)}</text>`).join('')}${f.rows.map(r=>`<circle cx="${x(r.day)}" cy="${y(r.balance)}" r="3" fill="${r.balance<p.cashFloor?'#c3a06f':'#7d9c68'}"><title>Day ${r.day}: ${money(r.balance)}</title></circle>`).join('')}</svg>`}
function plannerCalendar(){let p=currentPlan(),f=planForecast(p),offset=(new Date(state.month+'-01T12:00:00').getDay()+6)%7;return `<section class="panel calendar-panel"><div class="calendar-head"><div><h3>The timing matters, too.</h3><p class="intro">${monthName()} · Projected available cash after new earmarks</p></div><div class="calendar-key"><span><i class="legend-dot" style="background:#9cb287"></i>Expected receipt</span><span><i class="legend-dot" style="background:#d7c295"></i>Payment / earmark</span></div></div><div class="forecast-summary"><div><small>Starting funds</small><strong>${money(p.opening)}</strong><em>${p.partial?'Partial bank coverage':'Confirmed manual opening'}</em></div><div><small>Lowest projected</small><strong>${money(f.low.balance)}</strong><em>${f.low.day?'Day '+f.low.day:'Opening position'}</em></div><div><small>Closing available cash</small><strong>${money(f.end)}</strong><em>After new planned cash reservations</em></div><div><small>Your cash floor</small><strong>${money(p.cashFloor)}</strong><button class="tiny-button" data-plan-action="opening">Edit assumptions ↗</button></div></div>${plannerCashSVG(f,p)}<div class="cash-calendar">${['MON','TUE','WED','THU','FRI','SAT','SUN'].map(d=>`<div class="cal-weekday">${d}</div>`).join('')}${Array.from({length:offset},()=>'<div class="cal-day empty-day"></div>').join('')}${f.rows.map(r=>`<button class="cal-day ${r.balance<p.cashFloor?'low':''}" data-plan-day="${r.day}" aria-label="${r.day} ${plannerMonth(state.month)} projected available ${money(r.balance)}, ${r.events.length} events"><span class="cal-date">${String(r.day).padStart(2,'0')}</span>${r.events.slice(0,2).map(e=>`<span class="cal-event ${e.amount<0?'outflow':''}">${e.amount>0?'+':'−'} ${esc(e.title)}</span>`).join('')}${r.events.length>2?`<span class="cal-event">+${r.events.length-2} more</span>`:''}<span class="cal-balance">${money(r.balance)}</span></button>`).join('')}</div><div class="cash-agenda">${f.rows.filter(r=>r.events.length||r.day===f.low.day).map(r=>`<button class="agenda-day ${r.balance<p.cashFloor?'agenda-low':''}" data-plan-day="${r.day}"><span class="agenda-date"><b>${String(r.day).padStart(2,'0')}</b><small>${plannerMonth(state.month).slice(0,3)}</small></span><span class="agenda-detail"><b>${r.events.length?r.events.length+' planned '+(r.events.length===1?'movement':'movements'):'Cash low point'}</b>${r.events.slice(0,2).map(x=>`<small>${esc(x.title)}</small>`).join('')}${r.events.length>2?`<small>+ ${r.events.length-2} more</small>`:''}</span><span class="agenda-balance"><b>${money(r.balance)}</b><small>${r.balance<p.cashFloor?'Below cash floor':'Available after plans'}</small></span></button>`).join('')}</div><div class="info-strip">${p.partial?'◉ Partial forecast: unknown bank balances are excluded. ':''}Everyday allowances are spread across four weekly portions (7th, 14th, 21st, and month end). Receipts are modeled before payments on the same day; intraday clearance is not guaranteed. Internal transfers do not change the combined cash total. New planned card purchases reserve available funds for their future statement; they are not immediate bank payments. Existing statement dues settle prior liability. Avoid adding a second earmark or payment for the same planned purchase.</div><button class="view-all" data-plan-action="forecast-table">View accessible daily forecast table ↗</button></section>`}
function makeScenario(choice){let p=currentPlan(),s={choice,flex:100,extraInvestment:0,purchase:0,delay:0};if(choice==='invest')s.extraInvestment=10000;if(choice==='travel'){s.flex=90;s.purchase=25000}return s}
function scenarioItems(s=scenarioDraft){let items=structuredClone(currentPlan().items);items.forEach(x=>{if(x.lane==='everyday')x.amount=Math.round(x.amount*s.flex/100);if(['income','funding'].includes(x.kind))x.day=Math.min(new Date(+state.month.slice(0,4),+state.month.slice(5),0).getDate(),+x.day+s.delay)});if(s.extraInvestment>0)items.push({id:'scenario-invest-'+Date.now(),title:'Extra investment contribution',amount:s.extraInvestment,kind:'investment',lane:'future',day:20,category:'Mutual funds',source:'What-if studio · manual decision',enabled:true,account:planBanks()[0]?.name||'Manual opening pool',person:host.person,timing:'once',matchIds:[]});if(s.purchase>0)items.push({id:'scenario-purchase-'+Date.now(),title:scenarioChoice==='travel'?'A new adventure':'That purchase you’re considering',amount:s.purchase,kind:'expense',lane:'extras',day:18,category:'Shopping',source:'What-if studio · one-off estimate',enabled:true,account:planBanks()[0]?.name||'Manual opening pool',person:host.person,timing:'once',matchIds:[]});return items}
function plannerScenarios(){if(!scenarioDraft)scenarioDraft=makeScenario(scenarioChoice);let p=currentPlan(),cards=[['balanced','◒','Balanced month','Keep the current plan as your starting point.'],['invest','♧','Grow a little more',`Try an extra ${money(10000)} contribution.`],['travel','✧','Make a little memory',`Add ${money(25000)}, trim everyday allowances 10%.`]];return `<div class="plan-section-head"><div><h3>Try the month on, before you commit.</h3><p>Scenarios are drafts. Your current plan changes only when you apply one.</p></div>${planStatus(p)}</div><div class="scenario-cards">${cards.map(([k,icon,title,desc])=>{let s=makeScenario(k),m=planTotals(p,scenarioItems(s));return `<button class="scenario-card ${scenarioChoice===k?'selected':''}" data-plan-scenario="${k}"><span class="scenario-select"></span><span class="scenario-icon">${icon}</span><h3>${title}</h3><p>${desc}</p><div class="scenario-value num">${money(m.unallocated)}</div><div class="note">Projected month-end room</div></button>`}).join('')}</div><section class="panel"><div class="scenario-controls"><div><div class="plan-section-head"><h3>Make it your own</h3><span class="tag">Live preview</span></div>${[['flex','Everyday allowances',50,150,5,'%',scenarioDraft.flex,'Percentage of your current everyday plan.'],['extraInvestment','Extra investment',0,50000,1000,'',scenarioDraft.extraInvestment,'Additional external contribution; never consumption spending.'],['purchase','One-off purchase',0,100000,1000,'',scenarioDraft.purchase,'A new purchase on the 18th of the month.'],['delay','Receipt delay',0,28,1,' days',scenarioDraft.delay,'Stress-test what happens if income arrives later.']].map(([key,label,min,max,step,suffix,v,help])=>`<div class="range-field"><label for="scenario-${key}">${label}<b id="scenario-label-${key}">${key==='flex'?v+'%':key==='delay'?v+' days':money(v)}</b></label><input type="range" id="scenario-${key}" data-scenario-range="${key}" min="${min}" max="${max}" step="${step}" value="${v}"><p>${help}</p></div>`).join('')}</div><div class="scenario-impact"><small>Projected unallocated funds</small><strong id="scenario-room" class="num"></strong><p class="note" id="scenario-note"></p><div class="impact-row"><span>Planned consumption</span><b id="scenario-spend"></b></div><div class="impact-row"><span>Net investment</span><b id="scenario-invested"></b></div><div class="impact-row"><span>Lowest projected cash</span><b id="scenario-low"></b></div><div class="impact-row"><span>Days below your cash floor</span><b id="scenario-below"></b></div><button class="button primary" data-plan-action="apply-scenario" ${p.status==='closed'?'disabled':''}>Review & use this scenario →</button><button class="button" data-plan-action="save-scenario" style="margin-top:9px">Save scenario draft</button><p class="plan-help" style="margin-top:13px">${p.partial?'Partial forecast · one or more bank balances are unknown.':'Based on your manually confirmed opening.'} No payments are made.</p></div></div></section>${p.scenarios.length?`<section class="panel" style="margin-top:16px">${sectionHead('Your saved possibilities','Restore one to continue exploring')}${p.scenarios.map((s,i)=>`<button class="holding-row" data-plan-restore-scenario="${i}"><span><b>${esc(s.name)}</b><small>${s.date} · ${s.flex}% everyday · ${money(s.purchase)} one-off</small></span><span class="money">Restore →</span></button>`).join('')}</section>`:''}`}
function updateScenarioNumbers(){if(!$('#scenario-room'))return;let p=currentPlan(),items=scenarioItems(scenarioDraft),m=planTotals(p,items),f=planForecast(p,items),base=planTotals(p);$('#scenario-room').textContent=money(m.unallocated);$('#scenario-note').textContent=(m.unallocated<base.unallocated?money(base.unallocated-m.unallocated)+' less':money(m.unallocated-base.unallocated)+' more')+' room than your current plan.';$('#scenario-spend').textContent=money(m.spend);$('#scenario-invested').textContent=money(m.invested);$('#scenario-low').textContent=money(f.low.balance);$('#scenario-below').textContent=f.below;for(let k of ['flex','extraInvestment','purchase','delay'])$('#scenario-label-'+k).textContent=k==='flex'?scenarioDraft[k]+'%':k==='delay'?scenarioDraft[k]+' days':money(scenarioDraft[k])}
function fundKey(){return state.scope+':'+state.currency}
function currentFunds(){let k=fundKey();if(!plannerStore.funds[k]){plannerStore.funds[k]=[];planSave()}return plannerStore.funds[k]}
function fundNeed(f){let months=Math.max(1,(+f.date.slice(0,4)-+state.month.slice(0,4))*12+(+f.date.slice(5)-+state.month.slice(5))+1);return{months,monthly:Math.ceil(Math.max(0,f.target-f.saved)/months)}}
function plannerFundsView(){let funds=currentFunds(),p=currentPlan();return `<div class="plan-section-head"><div><h3>Big expenses. Small monthly steps.</h3><p>Build cash earmarks ahead of time, without treating them as spending.</p></div><button class="button primary" data-plan-action="add-fund">＋ New fund</button></div><div class="fund-grid">${funds.map(f=>{let n=fundNeed(f),linked=p.items.some(x=>x.fundId===f.id&&x.enabled);return `<section class="fund-card"><span class="fund-icon">${f.icon||'◉'}</span><h3>${esc(f.name)}</h3><div class="fund-value num">${money(f.saved)} <small>of ${money(f.target)}</small></div><div class="progress"><span style="width:${Math.min(100,f.saved/Math.max(f.target,1)*100)}%"></span></div><p>${money(Math.max(0,f.target-f.saved))} to go · Target ${monthName(f.date)}<br>Suggested ${money(n.monthly)} / month across ${n.months} planning months.</p><button class="button ${linked?'':'primary'}" data-plan-fund="${f.id}" ${linked||p.status==='closed'||!n.monthly?'disabled':''}>${linked?'✓ Earmark included in this plan':'+ Add '+money(n.monthly)+' to this month'}</button><button class="view-all" data-plan-edit-fund="${f.id}">Edit target & evidence ↗</button></section>`}).join('')||'<section class="panel empty"><h3>No funds yet</h3><p>Add a target for an annual bill, a purchase, or an emergency reserve.</p></section>'}</div><div class="info-strip">Saved amounts are planning earmarks within existing bank assets, not additional assets. New monthly earmarks reduce forecast available cash but do not reduce recorded bank cash or create an expense. Adding an earmark to a plan does not increase the fund’s saved balance; actual evidence must be recorded separately.</div>`}
function linkedActual(item){let ids=item.matchIds||[];return data().filter(t=>ids.includes(t.id))}
function actualForItem(item){return sum(linkedActual(item),t=>item.kind==='expense'?effect(t,'spending'):item.kind==='investment'||item.kind==='withdrawal'?effect(t,'invested'):t.amount)}
function plannerActual(){let p=currentPlan(),m=planTotals(p),actual=metrics(),a=data(),linked=new Set(p.items.flatMap(x=>x.matchIds||[])),unmatched=a.filter(t=>!linked.has(t.id)),cards=[['Earned income',m.income,actual.income],['Consumption spending',m.spend,actual.spending],['Net investment',m.invested,actual.invested]];return `<div class="plan-section-head"><div><h3>Intentions meet real life.</h3><p>Actuals come from the existing ledger. Matching records does not create new transactions.</p></div>${planStatus(p)}</div><div class="plan-actual-grid">${cards.map(([n,planned,actual])=>`<section class="actual-metric"><small>${n} · Actual / planned</small><strong>${money(actual)} <span class="currency-label">/ ${money(planned)}</span></strong><p>${money(Math.abs(planned-actual))} ${actual>planned?'above':'below'} plan</p><div class="progress" style="margin-top:13px"><span style="width:${planned?Math.min(100,Math.max(0,actual/planned*100)):0}%;background:${actual>planned?'#c39a70':'#93ad7e'}"></span></div></section>`).join('')}</div>${!a.length?'<div class="linked-budget">◷ No actual transactions recorded in this planning month. Your plan stays separate from the ledger. Record a transaction for this month to compare it with your plan.</div>':''}<section class="panel">${sectionHead('Connect the details',unmatched.length+' recorded transactions remain unmatched')}<div>${p.items.filter(x=>x.enabled&&x.kind!=='reserve'&&x.kind!=='transfer').map(x=>`<div class="match-row"><div><b>${esc(x.title)}</b><small>${planKindNames[x.kind]} · ${linkedActual(x).length} linked records · Planned ${money(x.amount)}</small></div><span class="money">${money(actualForItem(x))}</span><button class="button" data-plan-match="${x.id}" ${p.status==='closed'?'disabled':''}>Link actuals</button></div>`).join('')}</div><button class="view-all" data-plan-action="unmatched">Inspect unmatched transactions (${unmatched.length}) ↗</button></section>${p.activeLinks?`<div class="linked-budget" style="margin-top:16px">✓ Active revision ${p.activeLinks.revision} supplies ${p.activeLinks.budgets.length} consumption allowances and ${p.activeLinks.commitments.length} planned commitments. ${money(m.spend)} is your linked consumption budget.</div>`:'<p class="plan-help" style="margin-top:18px">Activate this draft to link its consumption allowances and dated commitments. No bank transactions will be posted.</p>'}`}
function renderPlannerBudget(){let p=currentPlan(),links=p.activeLinks;$('#content').innerHTML=`<div class="linked-budget">▦ Linked to ${esc(p.name)} · Revision ${links.revision} · ${p.status==='closed'?'Closed plan':'Active plan'}<br>Consumption allowances exclude investments, transfers, card payments, and cash reservations.</div><section class="panel">${sectionHead('Planner-linked category allowances',monthName()+' · '+scopeName())}${links.budgets.map(b=>{let actual=sum(data().filter(t=>t.category===b.category),t=>effect(t,'spending'));return `<button class="budget-line" data-category="${esc(b.category)}" style="display:block;width:100%;padding:0;text-align:left"><div><span>${esc(b.category)}</span><span>${money(actual)} / ${money(b.allowance)}</span></div><div class="progress"><span style="width:${Math.min(100,Math.max(0,actual/Math.max(1,b.allowance)*100))}%;background:${actual>b.allowance?'#c59970':'#8aa775'}"></span></div></button>`}).join('')}<button class="view-all" data-plan-action="back-plan">Open the linked monthly plan ↗</button></section>`}
function plannerItemForm(id,lane='extras',preset={}){let p=currentPlan(),existing=p.items.find(x=>x.id===id);if(p.status==='closed')return toast('Reopen this closed plan before making changes.');let x=existing||{id:null,title:'',amount:0,kind:lane==='income'?'income':lane==='future'?'investment':lane==='buffer'?'reserve':'expense',lane,day:1,category:lane==='income'?'Salary':lane==='future'?'Mutual funds':lane==='buffer'?'Cash buffer':'Shopping',account:planBanks()[0]?.name||'Manual opening pool',person:host.person,source:'Manual estimate',timing:lane==='everyday'?'weekly':'once',enabled:true,...preset};openDrawer(existing?'Shape this plan item':'Make room for something',`${scopeName()} · ${monthName()} · ${state.currency} · No ledger entry is created`, `<form id="planner-item-form" data-plan-item="${x.id||''}"><div class="field"><label for="plan-title">What are you planning?</label><input id="plan-title" name="title" value="${esc(x.title)}" required maxlength="100" placeholder="e.g. A weekend with family"></div><div class="form-grid"><div class="field"><label for="plan-amount">Amount · ${state.currency}</label><input id="plan-amount" name="amount" type="number" min="0" max="100000000" step=".01" value="${x.amount||''}" required></div><div class="field"><label for="plan-kind">Financial meaning</label><select id="plan-kind" name="kind">${Object.entries(planKindNames).map(([k,v])=>`<option value="${k}" ${x.kind===k?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label for="plan-lane">Planning lane</label><select name="lane" id="plan-lane"><option value="income" ${x.lane==='income'?'selected':''}>Expected receipts</option>${Object.entries(planLanes).map(([k,v])=>`<option value="${k}" ${x.lane===k?'selected':''}>${v.name}</option>`).join('')}</select></div><div class="field"><label for="plan-day">Day of month</label><input name="day" id="plan-day" type="number" min="1" max="${new Date(+state.month.slice(0,4),+state.month.slice(5),0).getDate()}" value="${x.day}" required></div><div class="field"><label for="plan-timing">Cash timing</label><select name="timing" id="plan-timing"><option value="once" ${x.timing==='once'?'selected':''}>Once on chosen day</option><option value="weekly" ${x.timing==='weekly'?'selected':''}>4 weekly portions</option></select></div><div class="field"><label for="plan-category">Category</label><input name="category" id="plan-category" value="${esc(x.category)}" list="plan-categories" required><datalist id="plan-categories">${[...Object.keys(categories),'Travel','Salary','Mutual funds','Stocks & ETF','Cash buffer','Card payment'].map(c=>`<option>${esc(c)}</option>`).join('')}</datalist></div><div class="field"><label for="plan-account">Funding / receipt account</label><select name="account" id="plan-account">${(accounts().length?accounts():[{name:'Manual opening pool'}]).map(a=>`<option ${a.name===x.account?'selected':''}>${esc(a.name)}</option>`).join('')}</select></div><div class="field"><label for="plan-person">Who funds this?</label><select name="person" id="plan-person">${host.people.map(v=>`<option ${x.person===v?'selected':''}>${esc(v)}</option>`).join('')}</select></div><div class="field"><label for="plan-destination">Destination (transfers / card payments)</label><input name="destination" id="plan-destination" value="${esc(x.destination||'')}" placeholder="Card or destination account"></div><div class="field"><label for="plan-source">Evidence / assumption</label><input name="source" id="plan-source" value="${esc(x.source)}" required></div></div><div class="info-strip">Income and household funding are different receipt types. Transfers between your own accounts do not create planning income or consumption. Cash earmarks reserve existing money. Card-funded consumption is earmarked for its future statement without posting a bank payment. Add separate statement payments only for existing prior liability, to avoid reserving a new purchase twice.</div><div class="form-actions">${existing?`<button type="button" class="button" data-plan-remove="${existing.id}">Remove item</button>`:''}<button type="button" class="button" data-action="close">Cancel</button><button class="button primary">Save plan item</button></div></form>`)}
function openingForm(){let p=currentPlan();if(p.status==='closed')return toast('Reopen this plan to change its starting assumptions.');openDrawer('Start with what you know',`${scopeName()} · ${monthName()} · ${state.currency}`,`<div class="formula"><b>Available starting funds</b>Use bank / cash balances minus existing earmarks. Card limits and expected income are not available cash.<br>${esc(p.openingSource)}</div><form id="planner-opening-form"><div class="field"><label for="plan-opening">Opening available funds · ${state.currency}</label><input id="plan-opening" name="opening" type="number" step=".01" min="0" value="${p.opening}" required></div><div class="field"><label for="plan-floor">Minimum available cash to protect · ${state.currency}</label><input id="plan-floor" name="floor" type="number" step=".01" min="0" value="${p.cashFloor}" required></div><div class="field"><label for="opening-evidence">Source / observation</label><input id="opening-evidence" name="source" value="${esc(p.openingSource)}" required></div><label class="compare" style="margin-top:20px;line-height:1.8"><input type="checkbox" name="complete" ${p.partial?'':'checked'}> I have verified all eligible same-currency opening funds and existing reserves.</label><div class="info-strip">These are planning assumptions. Saving them does not overwrite bank balance observations. Leave coverage unchecked if any balance is unknown.</div><div class="form-actions"><button type="button" class="button" data-action="close">Cancel</button><button class="button primary">Save opening assumptions</button></div></form>`)}
function plannerActivate(){let p=currentPlan(),m=planTotals(p),f=planForecast(p);openDrawer('Give your month a direction',`${esc(p.name)} · Revision ${p.revision} · ${scopeName()}`,`<div class="drawer-total num">${money(m.unallocated)} <span class="currency-label">${m.unallocated<0?'overallocated':'unallocated'}</span></div><div class="formula"><b>What activating this plan does</b>Links ${money(m.spend)} in consumption allowances to a local allowance view and saves local commitments for this revision. Server family budgets stay separate. Investments, card payments, transfers and earmarks remain separate. No actual transactions or bank payments are created.</div><div class="drawer-card"><h3>Before you begin</h3><p>${p.partial?'◉ Forecast coverage is partial. Unknown account balances are excluded.':'✓ Opening funds manually confirmed.'}<br>${f.below?`◷ ${f.below} days fall below your ${money(p.cashFloor)} cash floor.`:`✓ No forecast day falls below your ${money(p.cashFloor)} floor.`}<br>${m.unallocated<0?'⚠ Plan is overallocated. You can keep it as a draft and adjust it.':'✓ Planned allocations fit the modeled receipts and starting funds.'}</p></div><form id="planner-activate-form"><label class="compare" style="margin-top:20px;line-height:1.9"><input type="checkbox" required> I have reviewed the assumptions, coverage and cash timing.</label><div class="form-actions"><button type="button" class="button" data-action="close">Keep as draft</button><button class="button primary" ${m.unallocated<0?'disabled':''}>Activate this month’s plan</button></div></form>`)}
function plannerMatchForm(id){let p=currentPlan(),item=p.items.find(x=>x.id===id);if(!item||p.status==='closed')return;let used=new Set(p.items.filter(x=>x.id!==id).flatMap(x=>x.matchIds||[])),valid={expense:['expense','refund','behalf'],income:['income'],funding:['transfer'],investment:['investment','withdrawal'],withdrawal:['withdrawal'],card:['card'],reimbursement:['reimbursement'],transfer:['transfer']},candidates=data().filter(t=>(valid[item.kind]||[]).includes(t.type)&&!used.has(t.id));openDrawer('Connect plan to actuals',esc(item.title)+' · '+monthName(),`<div class="formula"><b>Link existing records only</b>Each actual transaction can be linked to one plan item. Actual monthly KPIs still include unmatched eligible records. No movement is duplicated.</div><form id="planner-match-form" data-item="${item.id}">${candidates.map(t=>`<label class="ritual-step"><input type="checkbox" name="match" value="${t.id}" ${(item.matchIds||[]).includes(t.id)?'checked':''}><span><b>${esc(t.description)} · ${money(item.kind==='expense'?effect(t,'spending'):t.amount)}</b><p>${dateLabel(t.date)} · ${esc(t.account)} · ${esc(t.category)} · ${types[t.type]}</p></span></label>`).join('')||'<div class="empty"><h3>No eligible unmatched records</h3><p>Add actuals for this month, or link records in a month with activity.</p></div>'}<div class="form-actions"><button type="button" class="button" data-action="close">Cancel</button><button class="button primary">Save links</button></div></form>`)}
function fundForm(id){let f=currentFunds().find(x=>x.id===id)||{name:'',target:0,saved:0,date:shiftMonth(state.month,6),category:'Cash goal'};openDrawer(id?'Shape your sinking fund':'Give a future expense a head start',scopeName()+' · '+state.currency,`<form id="planner-fund-form" data-fund="${id||''}"><div class="field"><label for="fund-name">Fund name</label><input id="fund-name" name="name" value="${esc(f.name)}" required></div><div class="form-grid"><div class="field"><label for="fund-target">Target · ${state.currency}</label><input type="number" min="1" step=".01" name="target" id="fund-target" value="${f.target||''}" required></div><div class="field"><label for="fund-saved">Evidence-backed existing earmark · ${state.currency}</label><input type="number" min="0" step=".01" name="saved" id="fund-saved" value="${f.saved}" required></div><div class="field"><label for="fund-date">Target month</label><input type="month" name="date" id="fund-date" value="${f.date}" required></div><div class="field"><label for="fund-category">Purpose</label><input name="category" id="fund-category" value="${esc(f.category)}" required></div></div><div class="info-strip">Saved funds must be backed by an existing bank asset. The same money cannot be earmarked to multiple goals. This planner records planning evidence only; it does not create or move money.</div><div class="form-actions"><button type="button" class="button" data-action="close">Cancel</button><button class="button primary">Save fund target</button></div></form>`)}
function plannerRitual(){let p=currentPlan(),prior=plannerStore.plans[[state.scope,state.currency,shiftMonth(state.month,-1)].join(':')],carry=prior?.items.filter(x=>x.enabled&&!['income','funding','reimbursement','withdrawal'].includes(x.kind)&&!x.matchIds?.length)||[];openDrawer('A fresh month, in five small steps',monthName()+' · '+scopeName(),`<p class="note">Start with evidence. Add what’s different. Make the plan yours.</p><form id="planner-ritual-form"><div class="ritual-steps">${[['carry','Bring forward unfinished plans',carry.length?carry.length+' unmatched prior-plan items can be copied. Unmatched is a review signal, not proof of nonpayment.':'No prior plan with unmatched commitments is recorded.'],['renewals','Check the quiet commitments','Review statement dues, observed subscription renewals and annual bills. Estimates remain labeled.'],['allowances','Make everyday life realistic','Starter allowances use last month’s net consumption. Edit them for the month you actually expect.'],['exceptions','Add what’s different','Travel, celebrations, home projects, guests or an important purchase.'],['funding','Check the timing, not just the total','Review your cash calendar, account coverage and dependency on future income.']].map(([key,title,desc])=>`<label class="ritual-step"><input type="checkbox" name="${key}" ${p.ritual[key]?'checked':''}><span><b>${title}</b><p>${desc}</p></span></label>`).join('')}</div>${carry.length?'<label class="compare" style="margin-top:18px"><input type="checkbox" name="copy"> Copy the unmatched prior-plan items for my review (no actuals).</label>':''}<div class="form-actions"><button type="button" class="button" data-action="close">Come back later</button><button class="button primary">Save my planning check-in</button></div></form>`)}
function plannerAction(a){let p=currentPlan();if(a==='opening')return openingForm();if(a==='receipts')return openDrawer('Expected receipts, explained',monthName()+' · '+scopeName(),`<div class="formula"><b>Expected ≠ received</b>Ordinary income, household funding, investment withdrawals and reimbursements are shown separately. A reimbursement is not earned income. Future amounts are assumptions until actual transactions appear.</div><div class="drawer-card">${p.items.filter(x=>['income','funding','reimbursement','withdrawal'].includes(x.kind)).map(x=>`<button class="holding-row" data-plan-edit="${x.id}"><span><b>${esc(x.title)}</b><small>${planKindNames[x.kind]} · Day ${x.day} · ${esc(x.source)}</small></span><span class="money">${money(x.amount)}</span></button>`).join('')}<button class="view-all" data-plan-action="add-income">＋ Add expected receipt</button></div>`);if(a==='allocation'){let m=planTotals(p);return openDrawer('Every part has a purpose',monthName()+' · '+scopeName()+' · '+state.currency,`<div class="drawer-total num">${money(m.unallocated)}</div><div class="formula"><b>Unallocated funds</b>Opening available ${money(p.opening)} + expected ordinary income ${money(m.income)} + household funding ${money(m.funding)} + reimbursements ${money(m.reimbursements)} + investment withdrawals ${money(m.withdrawals)}<br>− consumption ${money(m.spend)} − gross investment contributions ${money(m.contributions)} − card payments ${money(m.card)} − new cash earmarks ${money(m.reserve)}<br>= ${money(m.unallocated)}</div><div class="info-strip">Internal transfers are excluded from the aggregate equation. Existing reserves were already removed from opening available funds. Planned card-funded consumption sets aside available cash for its future statement; it is modeled as an earmark, not an immediate bank payment. Existing statement payments settle prior liability. All receipt assumptions carry timing risk.</div>`)}if(a==='add-income')return plannerItemForm(null,'income');if(a==='event')return openDrawer('What’s different this month?','Little moments deserve a place in the plan.',`<p class="note">Choose a starting point, then make the amount, timing and funding yours.</p><div class="event-choices">${[['trip','✈','A trip'],['celebration','✧','A celebration'],['home','⌂','A home project'],['purchase','▣','A big purchase']].map(([k,i,n])=>`<button class="event-choice" data-plan-event="${k}"><span>${i}</span>${n}</button>`).join('')}</div><button class="view-all" data-plan-add="extras">Something else →</button>`);if(a==='ritual')return plannerRitual();if(a==='activate')return plannerActivate();if(a==='history')return openDrawer('A plan that can evolve',esc(p.name)+' · Revision '+p.revision,`<div class="drawer-card"><h3>Local revision history</h3>${p.history.length?p.history.slice().reverse().map(h=>`<p>Revision ${h.revision} · ${esc(h.date)}<br>${esc(h.reason)}</p><div class="spacer"></div>`).join(''):'<p>Your starter draft has no revisions yet. Edits are recorded here.</p>'}</div>`);if(a==='close-plan')return openDrawer('Close this planning month',monthName()+' · '+scopeName(),`<div class="formula"><b>Keep a snapshot of your intentions</b>The plan becomes read-only. Actual transactions stay in the ledger. You can reopen the plan as a new draft later.</div><div class="form-actions"><button class="button" data-action="close">Keep active</button><button class="button primary" data-plan-action="confirm-close">Close plan</button></div>`);if(a==='confirm-close'){p.status='closed';p.history.push({revision:p.revision,date:new Date().toLocaleString('en-IN'),reason:'Plan closed; ledger retained'});planSave();closeDrawer();render();return toast('Plan closed. Actual ledger records were retained.')}if(a==='reopen'){p.status='draft';p.activeLinks=null;planRevise('Closed plan reopened as draft');render();return}if(a==='apply-scenario'){let items=scenarioItems(scenarioDraft),m=planTotals(p,items),f=planForecast(p,items);return openDrawer('Make this possibility your plan',monthName()+' · '+scopeName(),`<div class="formula"><b>Review the scenario</b>Everyday allowances ${scenarioDraft.flex}% of the base plan.<br>Extra investment ${money(scenarioDraft.extraInvestment)} · One-off purchase ${money(scenarioDraft.purchase)} · Receipt delay ${scenarioDraft.delay} days.<br>Result: ${money(m.unallocated)} unallocated · Lowest projected cash ${money(f.low.balance)}.</div><div class="info-strip">Applying replaces this draft’s plan items and creates a revision. Existing active budget links are retired until you reactivate the revised plan. No actuals or bank balances change.</div><div class="form-actions"><button class="button" data-action="close">Keep exploring</button><button class="button primary" data-plan-action="confirm-scenario">Use this scenario</button></div>`)}if(a==='confirm-scenario'){if(p.status==='closed')return;let items=scenarioItems(scenarioDraft);p.items=items;planRevise('What-if scenario applied to monthly draft');closeDrawer();plannerTab='canvas';render();return toast('Scenario applied as a new draft revision.')}if(a==='save-scenario'){p.scenarios.push({...scenarioDraft,name:{balanced:'Balanced month',invest:'Grow a little more',travel:'Make a little memory'}[scenarioChoice]+' · '+(p.scenarios.length+1),date:new Date().toLocaleDateString('en-IN')});planSave();renderPlanner();return toast('Scenario saved in this browser.')}if(a==='add-fund')return fundForm();if(a==='forecast-table'){let f=planForecast(p);return openDrawer('Daily cash forecast',monthName()+' · '+scopeName(),`<div class="table-scroll"><table class="ledger"><thead><tr><th>Day</th><th>Net payments / earmarks / receipts</th><th class="right">Available cash</th></tr></thead><tbody>${f.rows.map(r=>`<tr><td><button data-plan-day="${r.day}">${r.day} →</button></td><td>${money(sum(r.events,e=>e.amount))}</td><td class="right">${money(r.balance)}${r.balance<p.cashFloor?' · Below floor':''}</td></tr>`).join('')}</tbody></table></div>`)}if(a==='unmatched'){let ids=new Set(p.items.flatMap(x=>x.matchIds||[]));return openLedger('Unmatched actuals',data().filter(t=>!ids.has(t.id)))}if(a==='linked-budget'){closeDrawer();state.page='Budgets';render();return}if(a==='back-plan'){state.page='Planner';plannerTab='actual';render();return}}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset,p;if(d.planTab){plannerTab=d.planTab;closeDrawer();renderPlanner();return}if(d.planAction)return plannerAction(d.planAction);if(d.planEdit)return plannerItemForm(d.planEdit);if(d.planAdd)return plannerItemForm(null,d.planAdd);if(d.planEvent){const options={trip:{title:'A weekend away',category:'Travel'},celebration:{title:'A celebration with family',category:'Gifts & celebrations'},home:{title:'A home project',category:'Home & living'},purchase:{title:'A purchase worth planning for',category:'Shopping'}};return plannerItemForm(null,'extras',{...options[d.planEvent],day:20,source:'One-off event · manual estimate'})}if(d.planRemove){p=currentPlan();if(p.status==='closed')return;p.items=p.items.filter(x=>x.id!==d.planRemove);planRevise('Plan item removed; actual records retained');closeDrawer();render();return toast('Plan item removed. Ledger transactions retained.')}if(d.planDay){p=currentPlan();let f=planForecast(p),r=f.rows.find(x=>x.day===+d.planDay),prev=r.day===1?p.opening:f.rows[r.day-2].balance;return openDrawer(r.day+' '+monthName(),'Projected daily position · '+scopeName(),`<div class="drawer-total num">${money(r.balance)}</div><div class="formula"><b>Day-end available cash</b>Starting ${money(prev)} + net scheduled movements ${money(sum(r.events,x=>x.amount))} = ${money(r.balance)}<br>${p.partial?'Partial forecast: unknown account balances are excluded.':'Based on your confirmed opening assumption.'}</div><div class="drawer-card"><h3>Planned for this day</h3>${r.events.map(x=>`<button class="holding-row" data-plan-edit="${x.itemId}"><span><b>${esc(x.title)}</b><small>${x.kind==='earmark'?'New cash earmark':x.kind==='receipt'?'Expected receipt':'Planned bank cash payment'} · ${esc(x.account)}</small></span><span class="money">${money(x.amount)}</span></button>`).join('')||'<p>No scheduled movements.</p>'}</div>`)}if(d.planScenario){scenarioChoice=d.planScenario;scenarioDraft=makeScenario(scenarioChoice);renderPlanner();return}if(d.planRestoreScenario!==undefined){let s=currentPlan().scenarios[+d.planRestoreScenario];scenarioChoice=s.choice;scenarioDraft={...s};renderPlanner();return}if(d.planFund){p=currentPlan();if(p.status==='closed')return;let f=currentFunds().find(x=>x.id===d.planFund),need=fundNeed(f);if(p.items.some(x=>x.fundId===f.id&&x.enabled))return;p.items.push({id:'fund-item-'+Date.now(),fundId:f.id,title:f.name+' · monthly earmark',kind:'reserve',lane:'future',amount:need.monthly,day:1,timing:'once',category:f.category,person:state.scope==='personal'?'Prakhar':'Shared pool',account:state.scope==='personal'?'Axis Bank':'Axis Joint',source:'Goal target '+monthName(f.date)+' · cash earmark',enabled:true,matchIds:[]});planRevise('Sinking-fund monthly earmark added');renderPlanner();return toast('Monthly earmark added. No expense or asset was created.')}if(d.planEditFund)return fundForm(d.planEditFund);if(d.planMatch)return plannerMatchForm(d.planMatch)});
document.addEventListener('change',e=>{let d=e.target.dataset;if(d.planToggle){let p=currentPlan();if(p.status==='closed')return;let x=p.items.find(x=>x.id===d.planToggle);x.enabled=e.target.checked;planRevise((x.enabled?'Included ':'Excluded ')+x.title);renderPlanner()}});
document.addEventListener('input',e=>{let k=e.target.dataset.scenarioRange;if(k){scenarioDraft[k]=+e.target.value;updateScenarioNumbers()}});
document.addEventListener('submit',e=>{let form=e.target;if(!form.id.startsWith('planner-'))return;e.preventDefault();let f=new FormData(form),p=currentPlan();if(form.id==='planner-item-form'){if(p.status==='closed')return;let existing=p.items.find(x=>x.id===form.dataset.planItem),kind=f.get('kind'),lane=f.get('lane'),receipt=['income','funding','withdrawal','reimbursement'].includes(kind);if(receipt)lane='income';else if(lane==='income')lane=kind==='investment'?'future':kind==='reserve'?'buffer':'must';if(['transfer','card'].includes(kind)&&!String(f.get('destination')).trim())return toast('Add the destination account for this movement.');let x={...(existing||{}),id:existing?.id||'manual-'+Date.now(),title:String(f.get('title')).trim(),amount:+f.get('amount'),kind,lane,day:+f.get('day'),category:String(f.get('category')).trim(),source:String(f.get('source')).trim(),person:f.get('person'),account:f.get('account'),timing:f.get('timing'),destination:String(f.get('destination')).trim(),enabled:existing?.enabled??true,matchIds:existing?.kind===kind?existing.matchIds||[]:[]};if(!Number.isFinite(x.amount)||x.amount<0)return;if(existing)p.items[p.items.indexOf(existing)]=x;else p.items.push(x);planRevise((existing?'Updated ':'Added ')+x.title);closeDrawer();render();return toast('Plan updated. Forecast recalculated; ledger unchanged.')}if(form.id==='planner-opening-form'){p.opening=+f.get('opening');p.cashFloor=+f.get('floor');p.partial=!f.get('complete');p.openingConfirmed=true;p.openingSource=String(f.get('source'));planRevise('Opening funds and cash-floor assumptions updated');closeDrawer();render();return}if(form.id==='planner-activate-form'){if(planTotals(p).unallocated<0)return;let cats=[...new Set(p.items.filter(x=>x.enabled&&x.kind==='expense').map(x=>x.category))];p.activeLinks={revision:p.revision,budgets:cats.map(category=>({id:'plan-budget:'+planKey()+':'+category,category,allowance:sum(p.items.filter(x=>x.enabled&&x.kind==='expense'&&x.category===category),x=>x.amount)})),commitments:p.items.filter(x=>x.enabled&&!['income','funding','withdrawal','reserve'].includes(x.kind)).map(x=>({id:'plan-commitment:'+planKey()+':'+x.id,itemId:x.id,title:x.title,kind:x.kind,amount:x.amount,day:x.day}))};p.status='active';p.history.push({revision:p.revision,date:new Date().toLocaleString('en-IN'),reason:'Plan activated; consumption allowances and commitments linked'});planSave();closeDrawer();render();return toast('Plan active. Allowances linked; no ledger transactions posted.')}if(form.id==='planner-match-form'){let x=p.items.find(x=>x.id===form.dataset.item);x.matchIds=f.getAll('match');p.history.push({revision:p.revision,date:new Date().toLocaleString('en-IN'),reason:'Actual transaction links updated for '+x.title});planSave();closeDrawer();render();return toast('Existing records linked. Nothing was duplicated.')}if(form.id==='planner-fund-form'){let funds=currentFunds(),existing=funds.find(x=>x.id===form.dataset.fund),x={id:existing?.id||'goal-'+Date.now(),name:String(f.get('name')),target:+f.get('target'),saved:+f.get('saved'),date:f.get('date'),category:String(f.get('category')),icon:existing?.icon||'◉'};let knownReserve=sum(planBanks(),a=>a.reserve||0),other=sum(funds.filter(y=>y.id!==x.id),y=>y.saved);if(x.saved+other>knownReserve)return toast('Existing earmarks exceed recorded bank reserves. Verify reservations first.');if(existing)funds[funds.indexOf(existing)]=x;else funds.push(x);planSave();closeDrawer();renderPlanner();return toast('Fund target saved. No money moved.')}if(form.id==='planner-ritual-form'){for(let k of ['carry','renewals','allowances','exceptions','funding'])p.ritual[k]=!!f.get(k);if(f.get('copy')){let prev=plannerStore.plans[[state.scope,state.currency,shiftMonth(state.month,-1)].join(':')],n=0;for(let x of prev?.items.filter(x=>x.enabled&&!['income','funding','reimbursement','withdrawal'].includes(x.kind)&&!x.matchIds?.length)||[]){let carryFrom=shiftMonth(state.month,-1)+':'+x.id;if(!p.items.some(y=>y.carryFrom===carryFrom)){p.items.push({...structuredClone(x),id:'carry-'+Date.now()+'-'+(++n),matchIds:[],carryFrom,source:'Unmatched prior-plan item · needs review'});}}if(n)planRevise(n+' prior-plan items copied for review')}planSave();closeDrawer();render();return toast('Monthly planning check-in saved.')}});
// Reserve funds for new planned card consumption; do not model it as a bank payment.
const basePlanEvents=planEvents;planEvents=function(p=currentPlan(),items=p.items){let cashItems=items.map(x=>x.kind==='expense'&&accounts().some(a=>a.type==='card'&&a.name===x.account)?{...x,kind:'reserve',title:x.title+' · future statement reserve'}:x);return basePlanEvents(p,cashItems)};
let lastPlannerKey='';const plannerRenderOriginal=renderPlanner;renderPlanner=function(){if(lastPlannerKey!==planKey()){scenarioDraft=null;lastPlannerKey=planKey()}return plannerRenderOriginal()};
render();
